"use client";

/**
 * Rebuild control for a catalogue-mode wiki (KB settings → Wiki). Starts the
 * background regeneration and polls its progress. Pages are generated by
 * code from the legal catalogue; no LLM is involved.
 */
import { useCallback, useEffect, useRef, useState } from "react";
import { useT } from "@/lib/i18n";
import {
  getWikiCatalogueStatus,
  rebuildWikiCatalogue,
  type WikiCatalogueBuildStatus,
} from "@/lib/api/wiki";

export function WikiCatalogueRebuild({ kbId, enabled }: { kbId: string; enabled: boolean }) {
  const { t } = useT();
  const [status, setStatus] = useState<WikiCatalogueBuildStatus | null>(null);
  const [error, setError] = useState("");
  const [starting, setStarting] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const poll = useCallback(async () => {
    try {
      const st = await getWikiCatalogueStatus(kbId);
      setStatus(st);
      if (st?.running) {
        timer.current = setTimeout(poll, 2000);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  }, [kbId]);

  useEffect(() => {
    void poll();
    return () => {
      if (timer.current) clearTimeout(timer.current);
    };
  }, [poll]);

  const start = async () => {
    setStarting(true);
    setError("");
    try {
      const st = await rebuildWikiCatalogue(kbId);
      setStatus(st);
      if (timer.current) clearTimeout(timer.current);
      timer.current = setTimeout(poll, 1500);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setStarting(false);
    }
  };

  const running = Boolean(status?.running);
  return (
    <div className="rounded-md border border-hairline p-3">
      <div className="flex flex-wrap items-center gap-3">
        <button
          type="button"
          className="btn btn-outline btn-sm"
          onClick={start}
          disabled={!enabled || running || starting}
          title={!enabled ? t("kbSettings.wikiCatalogueSaveFirst") : undefined}
        >
          {running ? t("kbSettings.wikiCatalogueRunning") : t("kbSettings.wikiCatalogueRebuild")}
        </button>
        {status && (
          <span className="caption text-muted">
            {running
              ? `${t("kbSettings.wikiCataloguePhase")}: ${status.phase}${status.total ? ` · ${status.done}/${status.total}` : ""}`
              : status.error
                ? `${t("kbSettings.wikiCatalogueFailed")}: ${status.error}`
                : t("kbSettings.wikiCatalogueDone")
                    .replace("{created}", String(status.created))
                    .replace("{updated}", String(status.updated))
                    .replace("{skipped}", String(status.skipped))
                    .replace("{deleted}", String(status.deleted))}
          </span>
        )}
      </div>
      {!enabled && <p className="caption mt-2 text-muted">{t("kbSettings.wikiCatalogueSaveFirst")}</p>}
      {error && <p className="caption mt-2 text-danger">{error}</p>}
    </div>
  );
}
